import 'dart:convert';
import 'dart:io';
import 'package:app/services/conversation_search_index.dart';
import 'package:app/services/disk_search_index_io.dart';
import 'package:app/services/search_criteria.dart';
import 'package:app/services/search_scorer.dart';

Future<void> main(List<String> args) async {
  final samples = <Map<String, Object?>>[];
  final firstIds = <String, List<String>>{};
  final cgroup = File('/proc/self/cgroup').readAsLinesSync().singleWhere((s) => s.startsWith('0::')).substring(3);
  final memory = '/sys/fs/cgroup$cgroup';
  if (int.parse(File('$memory/memory.max').readAsStringSync().trim()) > 2000000000 || File('$memory/memory.swap.max').readAsStringSync().trim() != '0') throw StateError('Requires 2GB/no-swap cap');
  for (final query in ['search', 'metadata', 'create']) {
    for (final source in <String?>[null, 'group:email', 'imap']) {
      for (var sample = 0; sample < 3; sample++) {
        final prepare = Stopwatch()..start();
        final index = await DiskSearchIndex.open(path: args[0], vaultKey: List<int>.generate(32, (i) => i));
        try {
          if (await index.count != 100000) throw StateError('Wrong corpus size');
          await index.prepare();
          prepare.stop();
          for (final stage in ['prepared', 'warm']) {
            final clock = Stopwatch()..start();
            final tokens = ConversationSearchIndex.tokenize(query);
            final results = await index.search(SearchCriteria(query: query, source: source), SearchScorer(temporalIntent: null, normalizedQuery: query, now: DateTime.utc(2026,10,28)), tokens, tokens.join(' '));
            clock.stop();
            final ids = results.map((v) => v.id).toList();
            if (ids.length != 100 || ids.toSet().length != 100 || (source != null && results.any((v) => v.source != 'imap'))) throw StateError('Invalid paired-query results');
            final key = '$query/${source ?? 'all'}';
            final previous = firstIds.putIfAbsent(key, () => ids);
            if (jsonEncode(previous) != jsonEncode(ids)) throw StateError('Unstable ranking: $key');
            if (source == 'imap' && jsonEncode(ids) != jsonEncode(firstIds['$query/group:email'])) throw StateError('Provider/group ordering mismatch');
            final row = <String,Object?>{'query':query,'source':source,'sample':sample,'stage':stage,'prepareMs':prepare.elapsedMicroseconds/1000,'ms':clock.elapsedMicroseconds/1000,'profile':await index.searchProfile,'topIds':ids};
            samples.add(row);
            stdout.writeln(jsonEncode({...row,'topIds':ids.take(3).toList()}));
          }
        } finally { await index.close(); }
      }
    }
  }
  final result = {'count':100000,'samples':samples,'stableOrdering':true,'providerEqualsGroupOrdering':true,'peakRss':ProcessInfo.maxRss,'memoryMax':File('$memory/memory.max').readAsStringSync().trim(),'memoryPeak':File('$memory/memory.peak').readAsStringSync().trim(),'memoryEvents':File('$memory/memory.events').readAsStringSync(),'invocationId':Platform.environment['INVOCATION_ID']};
  await File(args[1]).writeAsString('${const JsonEncoder.withIndent('  ').convert(result)}\n');
}
